+    if (preg_match('/^(not used|not applicable|skipped)$/i', $head)) {
+        return 'not used';
+    }
+    if (preg_match('/^deferred$/i', $head)) {
+        return 'deferred';
+    }
+    $lower = strtolower($value);
+    if (str_contains($lower, 'verdict: yes') || preg_match('/\byes\b/', $lower) === 1) {
+        return 'yes';
+    }
+    if (preg_match('/\bno\b/', $lower) === 1) {
+        return 'no';
+    }
+    if (str_contains($lower, 'blocked')) {
+        return 'blocked';
+    }
+    if (str_contains($lower, 'defer')) {
+        return 'deferred';
+    }
+    return normalize_value($value);
